// (D104), a command without a row, in a transaction, and returns its result.
// It reads the table's rows and writes them only through their own
// operations, each held to its version, and presents no preconditions. It
// returns a refusal of the core's as the *rules.Refusal it is.
func (o deskCalendarOperations) FindAvailability(ctx context.Context, params DeskCalendarFindAvailabilityParams) (*DeskCalendarFindAvailabilityResult, error) {
	return inTransaction(ctx, o.r.database(), o.r.tx, func(tx pgx.Tx) (*DeskCalendarFindAvailabilityResult, error) {
		var out *DeskCalendarFindAvailabilityResult
		raw, err := rules.RunTableOperation(ctx, rulesHost(tx), "Desk", "Calendar", "findAvailability", params, behaviorCaller(ctx), nil)
		if err != nil {
			return out, err
		}
		out = &DeskCalendarFindAvailabilityResult{}
		if err := json.Unmarshal(raw, out); err != nil {
			return nil, fmt.Errorf("orm: the result of Desk's calendar findAvailability, %s: %w", raw, err)
		}
		return out, nil
	})
}

// coreOwn is row's own fields as the behaviors' core reads them (D103), by
// the layout's field names: each own column's value as encoding/json writes
