// operationOptions are the stamps an operation's write of the row sets, none
// on a table with no updatedAt or updatedBy.
func (r *DeskRepository) operationOptions(ctx context.Context) *rules.ExecuteOptions {
	return nil
}

// createThroughCore is CreateOne on the repository's transaction: input's row
// stamped, created by the behaviors' core, whose uses initialize the fields
// they own, with the columns the insert writes, and read back.
func (r *DeskRepository) createThroughCore(ctx context.Context, input *DeskCreate) (*types.Desk, error) {
	row := input.row()
	columns, err := r.createColumns(row)
	if err != nil {
		return nil, err
	}
	opts := &rules.CreateOptions{ID: r.createKey(row), ExecuteOptions: rules.ExecuteOptions{OwnColumns: columns}}
	key, err := rules.RunCreate(ctx, rulesHost(r.tx), "Desk", r.coreOwn(row), behaviorCaller(ctx), opts)
	if err != nil {
		return nil, err
	}
	id, err := types.ParseIdentityUUID(key)
	if err != nil {
		return nil, fmt.Errorf("create Desk: the core's key %q: %w", key, err)
	}
	return r.GetOne(ctx, id, nil)
}

// upsertInputs are inputs as an upsert inserts them (D103): each one's row
// with the fields its behaviors own as the core's create of it gives them,
// run to its change set and not applied, so the insert writes what CreateOne
// would have, and the update, which sets none of them, leaves them as the
// row holds them. A refusal of the core's is returned before anything is
// written.
func (r *DeskRepository) upsertInputs(ctx context.Context, inputs []*DeskCreate) ([]*types.Desk, error) {
	host := rulesHost(r.tx)
	rows := make([]*types.Desk, 0, len(inputs))
	for _, input := range inputs {
		row := input.row()
		_, err := rules.PrepareCreate(ctx, host, "Desk", r.coreOwn(row), behaviorCaller(ctx), &rules.CreateOptions{ID: r.createKey(row)})
		if err != nil {
			return nil, err
		}
		rows = append(rows, row)
	}
	return rows, nil
}

// Allowed fields for Desk (for validation and ordering)
var DeskAllowedFields = map[string]bool{
	"id":       true,
	"title":    true,
	"_version": true,
}

// Quoted field names for Desk (for SQL generation)
var DeskQuotedFields = map[string]string{
	"id":       `id`,
	"title":    `title`,
	"_version": `_version`,
}

// deskSortColumns are the columns of Desk's sort fields, by
// field, as FindPage's ORDER BY and keyset write them: qualified by the table,
// and by page_key, the alias of the subquery that reads the key's row. They
// are the only text of a sort that reaches its SQL (D60, amended). nulls is
// a column that may be null, whose nulls a page orders last (D112).
var deskSortColumns = map[DeskSortField]struct {
	sql, key string
	nulls    bool
}{
	DeskSortById:    {`desk.id`, `page_key.id`, false},
	DeskSortByTitle: {`desk.title`, `page_key.title`, false},
}

// buildDeskOrderByClause builds an ORDER BY clause for Desk.
// quotedTable is the table's name as the FROM clause spells it, quoted when
// it is a keyword (a table named order is "order").
func buildDeskOrderByClause(orderBy []DeskOrderBy, quotedTable string) string {
	if len(orderBy) == 0 {
		return ""
	}

	var clauses []string
	for _, order := range orderBy {
		fieldStr := string(order.Field)
		direction := "ASC"
		if order.Desc {
			direction = "DESC"
		}
		// Use pre-computed quoted field name
		quotedField, ok := DeskQuotedFields[fieldStr]
		if !ok {
			quotedField = fieldStr // Fallback to unquoted if not found
		}
		clauses = append(clauses, fmt.Sprintf("%s.%s %s", quotedTable, quotedField, direction))
	}

	if len(clauses) == 0 {
		return ""
	}

	return " ORDER BY " + strings.Join(clauses, ", ")
}

func deskUUIDValue(value any) (types.IdentityUUID, bool) {
	switch v := value.(type) {
	case types.IdentityUUID:
		return v, true
	case *types.IdentityUUID:
		if v == nil {
			var zero types.IdentityUUID
			return zero, false
		}
		return *v, true
	default:
		var zero types.IdentityUUID
		return zero, false
	}
}

func deskUUIDPtr(value types.IdentityUUID) *types.IdentityUUID {
	return &value
}

